-- Round 2026-10-03 stress test fix P31 (ROUND_PLAN_2026-10-03.md): the tool contracts the code now offers.
-- get_system_capabilities v2: each capability is derived from the effect of the tools offered in the
-- step (no list of tool names); v1 named tools that did not exist and reported no web capability
-- while find_web_fact was offered (stress test ma-qa-20261005a q7, P31).
-- prepare_data_bundle v2, open_analysis_session v2: row counts name their span (rows_extracted,
-- rows_in_ranges, buffer rows per range; P32). run_python v4: in_period and backtest (P32 layers 2-3).
-- complete_analysis orc-v2: the backtests are re-run by the backend (final_status.backtests).
-- Inactive like every market-ai-orc row; input schema and purpose from the code, every other column copied from the
-- previous version.
-- GENERATED by scripts/generate_tool_catalog_migration.py; market-ai-orc tests/test_data_need_tool.py fails on
-- drift. Do not edit by hand.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '1min';

DO $preflight$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE (tool_name, version) IN (('get_system_capabilities', 'v1'), ('prepare_data_bundle', 'v1'), ('open_analysis_session', 'v1'), ('run_python', 'v3'), ('complete_analysis', 'orc-v1'))) <> 5 THEN
        RAISE EXCEPTION 'Expected the previous tool versions (''get_system_capabilities'', ''v1''), (''prepare_data_bundle'', ''v1''), (''open_analysis_session'', ''v1''), (''run_python'', ''v3''), (''complete_analysis'', ''orc-v1'')';
    END IF;
    IF EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE (tool_name = 'get_system_capabilities' AND version = 'v2') OR (tool_name = 'prepare_data_bundle' AND version = 'v2') OR (tool_name = 'open_analysis_session' AND version = 'v2') OR (tool_name = 'run_python' AND version = 'v4') OR (tool_name = 'complete_analysis' AND version = 'orc-v2')) THEN
        RAISE EXCEPTION 'The stress test fix P31 tool versions are already registered';
    END IF;
END
$preflight$;

INSERT INTO public."Tool_Catalog" (
    tool_name, tool_family, tool_type, purpose, input_schema, output_schema,
    execution_type, handler_name, default_output_rows, max_output_rows,
    max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
    timeout_seconds, max_output_bytes, max_llm_result_rows,
    max_llm_result_bytes, max_llm_result_tokens,
    requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
    tool_specific_limits, version, is_active
)
SELECT tool_name, tool_family, tool_type, next.purpose, next.input_schema::jsonb, output_schema,
       execution_type, handler_name, default_output_rows, max_output_rows,
       max_input_rows, max_tickers, max_date_range_days, max_estimated_rows,
       timeout_seconds, max_output_bytes, max_llm_result_rows,
       max_llm_result_bytes, max_llm_result_tokens,
       requires_analytics_worker, requires_feature_catalog, requires_data_readiness,
       tool_specific_limits || '{"capabilities":"derived from ToolSpec.effect of the tools offered in the step (app/tools/system.py EFFECT_CAPABILITIES)","design":"ROUND_PLAN_2026-10-03.md (stress test fix P31)","registry_state":"registered from code (market-ai-orc) under the dev flags, inactive here"}'::jsonb, next.version, false
FROM public."Tool_Catalog" AS previous
JOIN (VALUES
    ('get_system_capabilities', 'v1', 'v2', '{"additionalProperties":false,"properties":{},"required":[],"type":"object"}',
     'Return what this agent can do in this step, derived from the tools it can call: each capability (read the catalog and earlier results, act on its own results, fetch market data from the database, look up one public fact on the web, run Python analysis) with the tools that provide it, the capabilities with no tool in this step, and the available tools.'),
    ('prepare_data_bundle', 'v1', 'v2', '{"additionalProperties":false,"properties":{"need_id":{"description":"need_id of an APPROVED DataNeedSpec.","type":"string"}},"required":["need_id"],"type":"object"}',
     'Extract and deliver the data of an APPROVED DataNeedSpec as one governed data bundle. The backend plans the physical extractions (column pruning, scope and join pushdown, merged or separate range windows, date or entity partitions) and the SQL Governor checks and extracts each part; nothing is sampled, truncated or re-scoped. The sandbox verifies every part, profiles the data and checks coverage. Returns READY with input_bundle_id and, per data request, rows_extracted (warm-up and forward buffer rows included), rows_in_ranges, entities, first/last date, each requested range with its actual bounds, its rows, the buffer rows before and after it and its status (OK, PARTIAL, EMPTY), quality_flags (e.g. NULL_VALUES, FREQUENCY_GAPS, HISTORY_BUFFER_SHORTFALL, EMPTY_ENTITY, DUPLICATE_KEYS) and relationship warnings; or REJECTED naming the data_request_id, the reason code and the next action. Quality flags are facts about the data to investigate and disclose, not failures. Never change the user''s scope to pass a limit: revise the DataNeedSpec only when the rejection says so.'),
    ('open_analysis_session', 'v1', 'v2', '{"additionalProperties":false,"properties":{"input_bundle_id":{"description":"input_bundle_id of a READY bundle.","type":"string"}},"required":["input_bundle_id"],"type":"object"}',
     'Open a persistent Python analysis session on a READY governed bundle (input_bundle_id from prepare_data_bundle). Returns session_id, the datasets (data_request_id, logical name, columns, rows_extracted with the buffer rows, rows_in_ranges inside the approved ranges, ranges, quality flags), the relationships with their join semantics, the helper functions and the limits. Variables and functions persist across run_python calls until the session closes (idle timeout, limits, or a restart of the sandbox: then open a new session on the same bundle).'),
    ('run_python', 'v3', 'v4', '{"additionalProperties":false,"properties":{"code":{"description":"Python to run in the session''s namespace.","type":"string"},"session_id":{"type":"string"}},"required":["session_id","code"],"type":"object"}',
     'Run Python in the session. pandas as pd, numpy as np and saniti with all its helpers are pre-bound; TA-Lib (import talib), scipy, statsmodels, polars, duckdb and matplotlib are available. Read data only through the helpers: load(request) returns a whole dataset (every row of every range, including warm-up history), load_range(request, range_id, include_buffers=False) one approved range (also saniti.range; plain range() is Python''s built-in), in_period(frame, request) the mask of the rows inside the approved ranges (count and summarise only those; warm-up rows feed indicators), sql(query) DuckDB over one view per logical name, join(relationship_id) the approved relationship with its point-in-time semantics, quality(request) the Data Quality Manifest, requests() and manifest() the bundle, resample(frame, request) the catalog rules. Reads outside the helpers count as not processed. Each dataset of the session shows materialize: DIRECT (load() may read it whole) or AGGREGATE_FIRST (reduce it in sql() first, e.g. GROUP BY its entity and date columns): load(), range() and sql() refuse a pandas frame larger than the session''s frame budget with MaterializationLimitExceeded, before anything is loaded; the session, its data and variables stay, so revise the code, never the data need. Write any logic you need; define functions and call them later. Emit results with emit_table(name, frame), emit_json(name, value), emit_text(name, text), emit_chart(figure, name, title), emit_file(name, data, format); emit_table and emit_json take units={column: ''FRACTION'' | ''PERCENT'' | ''P_VALUE''} for every column holding a share or a return as a decimal, a value already in percent, or a p-value, so the answer''s value references are formatted by the data''s unit, and definition={''filters'': [{''column'', ''operator'', ''value''}], ''period'': {''start'', ''end''}, ''entities'', ''thresholds'', ''notes''}: how the result was made beyond the data request (filters in the data need''s operators EQ, NEQ, GT, GTE, LT, LTE, IN, NOT_IN, BETWEEN, IS_NULL, IS_NOT_NULL; {} when the code applied none), which later turns read instead of guessing; complete_analysis does not release a table or JSON without one. A table of an earlier result opened with load_output carries its definition in .attrs; each returns output metadata and the tool result lists output_ids. print() is diagnostics only. Results: OK; SCRIPT_ERROR with error_type, line, field (e.g. a missing column) and traceback: fix the code and rerun (earlier variables remain); TIMEOUT (the execution was interrupted, the session remains); INSUFFICIENT_INPUT_DATA after saniti.insufficient_data(request, range_id, value, unit, reason): revise the DataNeedSpec (for example more history). No network, database, subprocess or writes outside intermediate_path(name). Named calendar-period returns (YTD, month, quarter, year, a comparable calendar period) use period_return(request, range_id, value_column=''close''): one row per entity with base_date, base_value (the last valid value strictly before the range start), end_date, end_value (the last valid value on or before the range end), return_decimal, return_pct (full precision) and calculation_status (COMPLETE, NO_PRIOR_CLOSE, NO_END_VALUE, INVALID_BASE_VALUE, INSUFFICIENT_INPUT_DATA, DUPLICATE_BOUNDARY_OBSERVATION); it needs history_buffer 1 TRADING_OBSERVATIONS on the request. Event study: event_study(request, event, outcome, horizon, range_id=None, overlap_policy=''NON_OVERLAPPING'', baseline=''ALL_ELIGIBLE'', min_events=None, holdout_start=None, outcome_unit=None, name=None) measures the outcome after an event against a baseline. event is a condition expression over the request''s columns, per entity and past values only (+ - * / **, comparisons, & | ~, abs log exp sqrt sign min max where, lag(x, k), rolling_sum(x, n), rolling_mean(x, n)), e.g. ''close / lag(close, 1) - 1 <= -0.05''; outcome is {''forward_return'': ''<price column>''} (add ''request'': ''<data_request_id>'' when the price is in another request); horizon counts observations; the request needs one row per entity and date. NON_OVERLAPPING keeps an entity''s next event only a horizon after the last one; ALL_ELIGIBLE compares with every row, NON_EVENT with the rows without the event; holdout_start adds IN_SAMPLE and OUT_OF_SAMPLE rows. It emits <name> (one row per segment: event_count, event_dates, effective_event_dates, mean, median, hit_rate, baseline_count, baseline_mean, baseline_median, delta_mean, delta_ci_low, delta_ci_high, delta_p_value with dates as clusters, censored_count, overlapping_dropped, meets_min_events), <name>_events (date, entity, outcome), <name>_baseline and <name>_flow (rows_in_window, condition_unknown, condition_true = the qualifying events, censored, overlapping_dropped, used; condition_true = censored + overlapping_dropped + used): quote each count from <name>_flow, never derive it; never overwrite or re-emit them. Backtest: backtest(request, frame, signal, exit_signal=None, stop=None, target=None, max_hold=None, fee=None, unit=None, prices=None, range_id=None, name=None) simulates long trades of a stated rule on the bundle prices: signal (and exit_signal) are boolean columns of your frame, True on the bar whose close triggers the order (filled at the next open); stop and target are fractions of the entry price; only bars inside the approved ranges trade (warm-up rows feed indicators). Use only the exit rules the user or the script states. It emits <name>_trades and <name>_summary (signals, trades, win_rate, mean and median return, average win and loss, realized_reward_risk, profit_factor, cumulative_return, max_drawdown, bars_in_period, bars_buffer): quote them, never overwrite or re-emit them.'),
    ('complete_analysis', 'orc-v1', 'orc-v2', '{"additionalProperties":false,"properties":{"session_id":{"type":"string"}},"required":["session_id"],"type":"object"}',
     'Finish the analysis of a session. The backend builds the ExecutionManifest and runs the Coverage Validator: every approved data request and range must have been delivered as approved and read in full through the saniti helpers in a successful execution, with at least one output. Returns final_status (data_coverage PASS/FAIL, sandbox_execution, calculation_validation NOT_PERFORMED, evidence_label, warnings, claims_allowed, claims_forbidden) and, on PASS, the released outputs with their content (JSON outputs and the first table rows). Only released outputs may be cited in the answer; disclose the warnings. On FAIL follow next_action: RUN_PYTHON (read what was not processed, then complete again), REVISE_DATA_NEED_SPEC, or REPORT_LIMITATION. The backend does not recalculate your formulas: never say a calculation was independently verified. Exception: the tables of saniti.event_study are recomputed by the backend from their declaration. final_status.event_studies lists each study (PASS, FAIL with CALCULATION_MISMATCH, INVALID) and verified_output_ids the matched tables; calculation_validation is then PARTIAL (other outputs exist) or FORMULA_AND_STATISTICS_VERIFIED. Only those tables may be called independently recalculated; a FAIL makes the completion INCOMPLETE: run the event study again and complete again. The tables of saniti.backtest are re-run by the backend on the bundle prices from their signal dates: final_status.backtests lists each (PASS, FAIL with CALCULATION_MISMATCH, INVALID); the signals themselves are the code''s and are not recomputed.')
) AS next(name, from_version, version, input_schema, purpose)
  ON previous.tool_name = next.name AND previous.version = next.from_version;

DO $verify$
BEGIN
    IF (SELECT count(*) FROM public."Tool_Catalog" WHERE NOT is_active AND ((tool_name = 'get_system_capabilities' AND version = 'v2') OR (tool_name = 'prepare_data_bundle' AND version = 'v2') OR (tool_name = 'open_analysis_session' AND version = 'v2') OR (tool_name = 'run_python' AND version = 'v4') OR (tool_name = 'complete_analysis' AND version = 'orc-v2'))) <> 5 THEN
        RAISE EXCEPTION 'The stress test fix P31 tool versions were not registered';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'get_system_capabilities' AND version = 'v2' AND purpose::text LIKE '%derived from the tools it can call%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'prepare_data_bundle' AND version = 'v2' AND purpose::text LIKE '%rows_in_ranges%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'open_analysis_session' AND version = 'v2' AND purpose::text LIKE '%rows_in_ranges%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'run_python' AND version = 'v4' AND purpose::text LIKE '%in_period%')
       OR NOT EXISTS (SELECT 1 FROM public."Tool_Catalog" WHERE tool_name = 'complete_analysis' AND version = 'orc-v2' AND purpose::text LIKE '%saniti.backtest%') THEN
        RAISE EXCEPTION 'The stress test fix P31 contracts are not in the registered rows';
    END IF;
END
$verify$;

COMMIT;
